	private class NextPreviousAction : MultiActionDockingAction {

		private static readonly int MOUSE_BUTTON_4 = 4;
		private static readonly int MOUSE_BUTTON_5 = 5;

		private bool isNext;

		NextPreviousAction(string name, string owner, bool isNext) : base(name, owner)
    {
			this.isNext = isNext;

			setToolBarData(new ToolBarData(isNext ? NEXT_ICON : PREVIOUS_ICON,
				ToolConstants.TOOLBAR_GROUP_TWO));
			setHelpLocation(new HelpLocation(HelpTopics.NAVIGATION, name));

			int keyCode = isNext ? KeyEvent.VK_RIGHT : KeyEvent.VK_LEFT;
			KeyStroke keyStroke = KeyStroke.getKeyStroke(keyCode, InputEvent.ALT_DOWN_MASK);

			int mouseButton = isNext ? MOUSE_BUTTON_5 : MOUSE_BUTTON_4;
			MouseBinding mouseBinding = new MouseBinding(mouseButton);

			setKeyBindingData(new KeyBindingData(new ActionTrigger(keyStroke, mouseBinding)));

			setDescription(isNext ? "Go to next location" : "Go to previous location");
			addToWindowWhen(typeof(NavigatableActionContext));
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			Navigatable navigatable = getNavigatable(context);
			if (navigatable == null) {
				return false;
			}
			if (isNext) {
				return historyService.hasNext(navigatable);
			}
			return historyService.hasPrevious(navigatable);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			Navigatable navigatable = getNavigatable(context);
			if (isNext) {
				historyService.next(navigatable);
			}
			else {
				historyService.previous(navigatable);
			}
		}

		/* @Override */
		public List<DockingActionIf> getActionList(ActionContext context) {
			Navigatable navigatable = getNavigatable(context);
			if (isNext) {
				return getNextActions(navigatable);
			}
			return getPreviousActions(navigatable);
		}

	}

	private static int idCount = 0;

	private class NavigationAction : DockingAction {
		private LocationMemento location;
		private Navigatable navigatable;
		private NavigationHistoryService service;
		private bool isNext;

		private NavigationAction(Navigatable navigatable, LocationMemento location, bool isNext,
				NavigationHistoryService service, CodeUnitFormat formatter) : base("NavigationAction: " + ++idCount, this.getName())
    {
			this.location = location;
			this.isNext = isNext;
			this.service = service;
			this.navigatable = navigatable;

			Icon navIcon = navigatable.getNavigatableIcon();
			setHelpLocation(new HelpLocation(HelpTopics.NAVIGATION, "Navigation_History"));
			setMenuBarData(
				new MenuData(new string[] { buildActionName(location, formatter) }, navIcon));
			setEnabled(true);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			if (isNext) {
				service.next(navigatable, location);
			}
			else {
				service.previous(navigatable, location);
			}
		}
	}

	private class NextPreviousFunctionAction : DockingAction {

		private bool isNext;

		NextPreviousFunctionAction(string name, string owner, bool isNext) : base(name, owner)
    {
			this.isNext = isNext;

			setHelpLocation(new HelpLocation(HelpTopics.NAVIGATION, name));
			int keycode = isNext ? KeyEvent.VK_RIGHT : KeyEvent.VK_LEFT;
			setKeyBindingData(
				new KeyBindingData(keycode, InputEvent.ALT_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK));
			setDescription(
				isNext ? "Go to next function location" : "Go to previous function location");

			string menuItemName = isNext ? "Next History Function" : "Previous History Function";
			MenuData menuData =
				new MenuData(new string[] { "Navigation", menuItemName }, HISTORY_MENU_GROUP);
			menuData.setMenuSubGroup("2"); // after clear
			setMenuBarData(menuData);
			addToWindowWhen(typeof(NavigatableActionContext));
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			Navigatable navigatable = getNavigatable(context);
			if (navigatable == null) {
				return false;
			}
			if (isNext) {
				return historyService.hasNextFunction(navigatable);
			}
			return historyService.hasPreviousFunction(navigatable);
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			Navigatable navigatable = getNavigatable(context);
			if (isNext) {
				historyService.nextFunction(navigatable);
			}
			else {
				historyService.previousFunction(navigatable);
			}
		}
	}

}
